-- seed_data.sql
-- Data-only seed for return_game (every row currently in the DB).
-- Run AFTER schema_structure.sql:  mysql return_game < seed_data.sql
--
-- The 5 aggregate triggers are dropped before the load and recreated after it, so the
-- authoritative player_global_stats rows below load exactly as captured instead of being
-- recomputed/duplicated by the triggers as the child rows insert. FK/unique checks are
-- disabled during load so table order does not matter.

USE `return_game`;

SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0;
SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0;

DROP TRIGGER IF EXISTS trg_player_profiles_ai_bootstrap;
DROP TRIGGER IF EXISTS trg_sed_ai_count;
DROP TRIGGER IF EXISTS trg_parry_ai_count;
DROP TRIGGER IF EXISTS trg_player_cards_ai_count;
DROP TRIGGER IF EXISTS trg_runs_au_finish;
-- (trg_active_deck_cards_bi_maxsize is left active; <=5 cards/session never trips it.)

